import { createHash } from "node:crypto";
import {
  chmodSync,
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";

const RULES_REL = ".guardrail/rules.yml";
const CURSOR_HOOKS = ".cursor/hooks.json";
const CLAUDE_SETTINGS = ".claude/settings.json";
const CURSOR_GUARD = ".cursor/hooks/rulecloud-guard.sh";
const CLAUDE_GUARD = ".claude/hooks/rulecloud-guard.sh";
const PARITY_VERSION = 1;

const GUARD_SCRIPT = `#!/usr/bin/env bash
# Generated by rulecloud sync-hooks — do not edit by hand.
set -euo pipefail

DIR="$(cd "$(dirname "$0")" && pwd)"
case "$DIR" in
  *"/.cursor/hooks")
    ROOT="$(cd "$DIR/../.." && pwd)"
    META="$ROOT/.cursor/hooks.json"
    ;;
  *"/.claude/hooks")
    ROOT="$(cd "$DIR/../.." && pwd)"
    META="$ROOT/.claude/settings.json"
    ;;
  *)
    echo "rulecloud-guard: unexpected hook path" >&2
    exit 2
    ;;
esac

RULES="$ROOT/.guardrail/rules.yml"
if [[ ! -f "$RULES" ]]; then
  echo "Missing .guardrail/rules.yml" >&2
  exit 2
fi

HASH="$(node -e "
const fs=require('fs');
const p=process.argv[1];
const j=JSON.parse(fs.readFileSync(p,'utf8'));
const h=j.rulecloud?.rulesSha256;
if(!h){process.exit(3);}
process.stdout.write(h);
" "$META" 2>/dev/null || true)"

if [[ -z "$HASH" ]]; then
  echo "Hook metadata missing rulecloud.rulesSha256 — run: rulecloud sync-hooks" >&2
  exit 2
fi

ACTUAL="$(openssl dgst -sha256 "$RULES" | awk '{print $NF}')"
if [[ "$HASH" != "$ACTUAL" ]]; then
  echo "Guardrail drift: .guardrail/rules.yml changed without hook sync. Run: rulecloud sync-hooks" >&2
  exit 2
fi

# Cursor/Claude hook payload (may be empty when invoked manually).
PAYLOAD="$(cat || true)"

# Block native file tools / shell when they target protected paths (e.g. .env).
# Heredoc keeps quotes/backticks out of bash parsing (node -e single-quotes break easily).
export RULECLOUD_HOOK_PAYLOAD="$PAYLOAD"
node <<'NODE'
const raw = process.env.RULECLOUD_HOOK_PAYLOAD || "";
let obj = {};
try { obj = raw ? JSON.parse(raw) : {}; } catch { obj = {}; }
const ti = (obj.tool_input && typeof obj.tool_input === "object") ? obj.tool_input : {};
const paths = [obj.file_path, obj.path, ti.file_path, ti.path]
  .filter((x) => typeof x === "string" && x.length > 0);
const command = [obj.command, ti.command]
  .filter((x) => typeof x === "string" && x.length > 0)
  .join("\\n");

function baseName(p) {
  const n = String(p).replace(/\\\\/g, "/");
  const i = n.lastIndexOf("/");
  return i >= 0 ? n.slice(i + 1) : n;
}
function isProtectedPath(p) {
  const b = baseName(p);
  if (b === ".env") return true;
  if (b.startsWith(".env.") && b !== ".env.example") return true;
  return false;
}
for (const p of paths) {
  if (isProtectedPath(p)) {
    console.error("BLOCKED: refusing access to protected path: " + p);
    process.exit(2);
  }
}
if (command) {
  const tokens = command.split(/\\s+/).map((t) => t.replace(/^["']+|["']+$/g, "")).filter(Boolean);
  for (const t of tokens) {
    if (isProtectedPath(t)) {
      console.error("BLOCKED: refusing access to protected path via command: " + t);
      process.exit(2);
    }
  }
}
NODE
unset RULECLOUD_HOOK_PAYLOAD

# Cursor preToolUse / beforeReadFile expect JSON on stdout when the hook succeeds.
if [[ "$META" == *".cursor/hooks.json" ]]; then
  echo '{"permission":"allow"}'
fi

exit 0
`;

export type SyncHooksResult = {
  rulesSha256: string;
  wrote: string[];
};

function rulesPath(cwd: string): string {
  return path.join(cwd, RULES_REL);
}

export function sha256Rules(cwd: string): string {
  const rulesFile = rulesPath(cwd);
  if (!existsSync(rulesFile)) {
    throw new Error(`Missing ${RULES_REL} — run rulecloud init first`);
  }
  const body = readFileSync(rulesFile, "utf8");
  return createHash("sha256").update(body, "utf8").digest("hex");
}

function rulecloudMeta(hash: string): { rulecloud: { version: number; rulesSha256: string; rulesPath: string } } {
  return {
    rulecloud: {
      version: PARITY_VERSION,
      rulesSha256: hash,
      rulesPath: RULES_REL,
    },
  };
}

function buildCursorHooks(hash: string): Record<string, unknown> {
  return {
    version: 1,
    ...rulecloudMeta(hash),
    hooks: {
      preToolUse: [
        {
          command: ".cursor/hooks/rulecloud-guard.sh",
          matcher: "Shell|Read|Write|Edit|Delete",
          failClosed: true,
        },
      ],
      beforeReadFile: [
        {
          command: ".cursor/hooks/rulecloud-guard.sh",
          failClosed: true,
        },
      ],
    },
  };
}

function buildClaudeSettings(hash: string): Record<string, unknown> {
  return {
    ...rulecloudMeta(hash),
    requiredMinimumVersion: "2.1.295",
    hooks: {
      PreToolUse: [
        {
          matcher: "Bash",
          hooks: [
            {
              type: "command",
              command: `\${CLAUDE_PROJECT_DIR}/${CLAUDE_GUARD}`,
              timeout: 30,
              onFailure: "block",
            },
          ],
        },
      ],
    },
  };
}

function writeExecutable(filePath: string, body: string): void {
  mkdirSync(path.dirname(filePath), { recursive: true });
  writeFileSync(filePath, body, "utf8");
  try {
    chmodSync(filePath, 0o755);
  } catch {
    /* windows */
  }
}

function writeJson(filePath: string, data: Record<string, unknown>): void {
  mkdirSync(path.dirname(filePath), { recursive: true });
  writeFileSync(filePath, JSON.stringify(data, null, 2) + "\n", "utf8");
}

function readJson(filePath: string): Record<string, unknown> | null {
  if (!existsSync(filePath)) return null;
  try {
    return JSON.parse(readFileSync(filePath, "utf8")) as Record<string, unknown>;
  } catch {
    return null;
  }
}

function metaHash(doc: Record<string, unknown> | null): string | null {
  if (!doc) return null;
  const rc = doc.rulecloud;
  if (!rc || typeof rc !== "object") return null;
  const h = (rc as { rulesSha256?: string }).rulesSha256;
  return typeof h === "string" ? h : null;
}

function claudeHasFailClosed(settings: Record<string, unknown> | null): boolean {
  if (!settings?.hooks || typeof settings.hooks !== "object") return false;
  const pre = (settings.hooks as { PreToolUse?: unknown[] }).PreToolUse;
  if (!Array.isArray(pre)) return false;
  for (const group of pre) {
    if (!group || typeof group !== "object") continue;
    const inner = (group as { hooks?: unknown[] }).hooks;
    if (!Array.isArray(inner)) continue;
    for (const hook of inner) {
      if (hook && typeof hook === "object" && (hook as { onFailure?: string }).onFailure === "block") {
        return true;
      }
    }
  }
  return false;
}

function isRulecloudFailClosedHook(h: unknown): boolean {
  return (
    !!h &&
    typeof h === "object" &&
    (h as { failClosed?: boolean }).failClosed === true &&
    String((h as { command?: string }).command || "").includes("rulecloud-guard")
  );
}

function cursorHasFailClosed(hooks: Record<string, unknown> | null): boolean {
  if (!hooks?.hooks || typeof hooks.hooks !== "object") return false;
  const bag = hooks.hooks as { preToolUse?: unknown[]; beforeReadFile?: unknown[] };
  const pre = bag.preToolUse;
  const beforeRead = bag.beforeReadFile;
  if (!Array.isArray(pre) || !Array.isArray(beforeRead)) return false;
  return pre.some(isRulecloudFailClosedHook) && beforeRead.some(isRulecloudFailClosedHook);
}

export function runSyncHooks(cwd: string, check: boolean): number {
  const hash = sha256Rules(cwd);
  const cursorPath = path.join(cwd, CURSOR_HOOKS);
  const claudePath = path.join(cwd, CLAUDE_SETTINGS);
  const cursorGuardPath = path.join(cwd, CURSOR_GUARD);
  const claudeGuardPath = path.join(cwd, CLAUDE_GUARD);

  const expectedCursor = buildCursorHooks(hash);
  const expectedClaude = buildClaudeSettings(hash);
  const expectedGuard = GUARD_SCRIPT;

  if (check) {
    const errors: string[] = [];
    if (!existsSync(cursorPath)) errors.push(`missing ${CURSOR_HOOKS}`);
    if (!existsSync(claudePath)) errors.push(`missing ${CLAUDE_SETTINGS}`);
    if (!existsSync(cursorGuardPath)) errors.push(`missing ${CURSOR_GUARD}`);
    if (!existsSync(claudeGuardPath)) errors.push(`missing ${CLAUDE_GUARD}`);

    const cursorDoc = readJson(cursorPath);
    const claudeDoc = readJson(claudePath);

    if (metaHash(cursorDoc) !== hash) {
      errors.push(`${CURSOR_HOOKS} rulecloud.rulesSha256 does not match ${RULES_REL}`);
    }
    if (metaHash(claudeDoc) !== hash) {
      errors.push(`${CLAUDE_SETTINGS} rulecloud.rulesSha256 does not match ${RULES_REL}`);
    }
    if (!cursorHasFailClosed(cursorDoc)) {
      errors.push(
        `${CURSOR_HOOKS} must set failClosed: true on rulecloud-guard preToolUse and beforeReadFile hooks`,
      );
    }
    if (!claudeHasFailClosed(claudeDoc)) {
      errors.push(
        `${CLAUDE_SETTINGS} must include PreToolUse hook with onFailure: "block" (Claude Code v2.1.295+)`,
      );
    }
    const minVer = claudeDoc?.requiredMinimumVersion;
    if (minVer !== "2.1.295") {
      errors.push(
        `${CLAUDE_SETTINGS} must set requiredMinimumVersion: "2.1.295" for onFailure support`,
      );
    }

    if (existsSync(cursorGuardPath) && readFileSync(cursorGuardPath, "utf8") !== expectedGuard) {
      errors.push(`${CURSOR_GUARD} out of date — run rulecloud sync-hooks`);
    }
    if (existsSync(claudeGuardPath) && readFileSync(claudeGuardPath, "utf8") !== expectedGuard) {
      errors.push(`${CLAUDE_GUARD} out of date — run rulecloud sync-hooks`);
    }

    if (JSON.stringify(cursorDoc) !== JSON.stringify(expectedCursor)) {
      errors.push(`${CURSOR_HOOKS} structure drifts from sync-hooks template`);
    }
    if (JSON.stringify(claudeDoc) !== JSON.stringify(expectedClaude)) {
      errors.push(`${CLAUDE_SETTINGS} structure drifts from sync-hooks template`);
    }

    if (errors.length) {
      console.error("Hook parity check failed:\n");
      for (const e of errors) console.error(`  • ${e}`);
      console.error("\nFix: rulecloud sync-hooks");
      return 1;
    }
    console.log(`Hook parity OK (${RULES_REL} sha256=${hash.slice(0, 12)}…)`);
    console.log("  Claude: PreToolUse onFailure=block (requires Claude Code v2.1.295+)");
    console.log(
      "  Cursor: preToolUse failClosed=true (Shell|Read|Write|Edit|Delete) + beforeReadFile",
    );
    return 0;
  }

  writeJson(cursorPath, expectedCursor);
  writeJson(claudePath, expectedClaude);
  writeExecutable(cursorGuardPath, expectedGuard);
  writeExecutable(claudeGuardPath, expectedGuard);

  console.log(`Synced hook parity for ${RULES_REL}`);
  console.log(`  sha256: ${hash}`);
  console.log(`  Wrote ${CURSOR_HOOKS} (failClosed guard)`);
  console.log(`  Wrote ${CLAUDE_SETTINGS} (onFailure: block)`);
  console.log(`  Wrote ${CURSOR_GUARD} and ${CLAUDE_GUARD}`);
  return 0;
}